WITH ranked AS (SELECT * FROM (SELECT *, ROW_NUMBER() OVER (PARTITION BY status ORDER BY cost DESC NULLS LAST, id) AS rn FROM shipments) t WHERE rn = 1), scored AS (SELECT *, SUM(cost) OVER (PARTITION BY MONTH(shipped_date), carrier ORDER BY shipped_date, id ROWS BETWEEN UNBOUNDED PRECEDING AND CURRENT ROW) AS running_cost, LEAD(cost, 1) OVER (PARTITION BY carrier ORDER BY shipped_date, id) AS next_cost, DENSE_RANK() OVER (PARTITION BY status ORDER BY cost DESC NULLS FIRST) AS cost_dense_rank FROM ranked), valid AS (SELECT id, carrier, shipped_date, cost, status, rn, running_cost, next_cost, cost_dense_rank, DATEDIFF(delivered_date, shipped_date) / 7 AS weeks_shipped_date_to_delivered_date FROM scored WHERE shipped_date >= DATE '2023-09-21' AND order_id IS NOT NULL), metrics AS (SELECT *, PERCENT_RANK() OVER (PARTITION BY carrier, status ORDER BY cost_dense_rank DESC NULLS LAST) AS cost_dense_rank_percent_rank, AVG(weeks_shipped_date_to_delivered_date) OVER (PARTITION BY DATE_TRUNC('MONTH', shipped_date), carrier ORDER BY shipped_date, id ROWS BETWEEN 5 PRECEDING AND CURRENT ROW) AS weeks_shipped_date_to_delivered_date_avg_5, LAST_VALUE(next_cost, TRUE) OVER (PARTITION BY carrier, status ORDER BY running_cost, id ROWS BETWEEN UNBOUNDED PRECEDING AND CURRENT ROW) AS last_known_next_cost FROM valid) SELECT CASE WHEN cost >= 84 THEN 'PREMIUM' ELSE 'STANDARD' END AS cost_tier, COUNT(DISTINCT carrier) AS distinct_carriers, COUNT(*) AS cnt FROM metrics GROUP BY CASE WHEN cost >= 84 THEN 'PREMIUM' ELSE 'STANDARD' END;
